(()=>{'use strict';const T={squat:['Присед до комфортной глубины','Стопы устойчиво, колени по линии носков. Напряги корпус и сохраняй нейтральную спину.','Не заваливай колени внутрь и не округляй поясницу.'],bench:['Жим лёжа','Лопатки сведены и прижаты к скамье, стопы устойчивы. Опускай снаряд контролируемо к нижней части груди.','Не отбивай вес от груди.'],pulldown:['Тяга блока','Начни с опускания лопаток, тяни рукоять к верхней части груди и возвращай вес под контролем.','Не раскачивай корпус и не тяни только руками.'],core:['Корпус','Сохраняй рёбра и таз собранными, дыши без потери напряжения.','Не прогибай поясницу ради времени или повторов.'],rdl:['Румынская тяга','Колени мягкие, спина нейтральная. Отводи таз назад и веди вес близко к ногам до натяжения задней поверхности бедра.','Не превращай движение в присед и не округляй спину.'],dbbench:['Жим гантелей лёжа','Лопатки собраны, стопы устойчивы. Опускай гантели контролируемо по сторонам груди.','Не опускай локти слишком далеко ниже корпуса при дискомфорте.'],row:['Тяга горизонтального блока','Потяни рукоять к нижним рёбрам, своди лопатки без переразгибания поясницы.','Не раскачивайся и не выдвигай голову вперёд.'],dbpress:['Жим гантелей сидя','Корпус и таз устойчивы. Жми гантели вверх в комфортной траектории и контролируй опускание.','Не компенсируй вес сильным прогибом в пояснице.']};const RDL='data:image/webp;base64,';const style=document.createElement('style');style.textContent='.fx-tech-img{display:block;width:100%;max-height:210px;object-fit:contain;margin:10px 0;border:1px solid #244a64;border-radius:13px;background:#07111c}';document.head.appendChild(style);document.addEventListener('click',e=>{const b=e.target.closest('[data-info]'),x=T[b?.dataset.info];if(!x)return;e.preventDefault();e.stopImmediatePropagation();document.getElementById('fxSheet')?.remove();const image=b.dataset.info==='rdl'?'<img class="fx-tech-img" src="'+RDL+'" alt="Румынская тяга: стартовая и конечная позиция">':'';const s=document.createElement('div');s.id='fxSheet';s.className='fx-sheet';s.innerHTML='<div><div class="fx-eye">ТЕХНИКА УПРАЖНЕНИЯ</div><h3>'+x[0]+'</h3>'+image+'<p>'+x[1]+'</p><p class="fx-warn"><b>Избегай:</b> '+x[2]+'</p><p class="fx-note">Остановись при резкой боли или необычном дискомфорте.</p><button class="fx-close">ПОНЯТНО</button></div>';document.body.appendChild(s);s.onclick=q=>{if(q.target===s||q.target.classList.contains('fx-close'))s.remove()}},true);})();

